  return {
    id,
    taskId: task.id,
    taskTitle: task.title.trim(),
    durationMilliseconds: durationMilliseconds(minutes),
    focusedMilliseconds: 0,
    startedAt,
    status: 'running',
    lastResumedAt: startedAt
